def test_m272_runtime_is_fail_closed_and_ordered():
 s=read('scripts/online/m272_npc_monster_ai_combat_brain_runtime.gd')
 for t in ['bind_targeting','ingest_server_brain_snapshot','ingest_server_ai_decision','local_ai_presentation_hint','brain_revision','decision_sequence','threat_state','navigation_state','combat_intent_state','leash_state','phase_state','invalidate_from_world_resync']: assert t in s
 for t in ['can_client_choose_ai_target() -> bool: return false','can_client_set_ai_state() -> bool: return false','can_client_set_threat() -> bool: return false','can_client_authorize_ai_attack() -> bool: return false','can_client_override_leash() -> bool: return false','can_client_force_boss_phase() -> bool: return false','can_client_confirm_ai_path() -> bool: return false','can_client_transfer_test_ai_state_to_global() -> bool: return false']: assert t in s
 assert '"can_commit_ai_decision":false' in s and 'revision <= brain_revision' in s and 'sequence <= decision_sequence' in s
